import base64,hashlib,json,os,shutil,subprocess
from pathlib import Path
SHA='b5df776a88bdfa961e60f60d6076c6915f37c5fd5ed8ade973dc4be7205eea6c'
PREVIOUS='24d6fad3174f765d3433c9ab71322f04241b11acf0224a4e1392f138295adf0c'
raw=base64.b64decode('')
assert hashlib.sha256(raw).hexdigest()==SHA
assert subprocess.check_output(['findmnt','-n','-o','UUID','--target','/mnt/data-disk']).decode().strip()=='3e8ac4e8-7770-456d-9e89-2ec5dd405fa8'
assert subprocess.check_output(['findmnt','-n','-o','TARGET','--target','/mnt/data-disk']).decode().strip()=='/mnt/data-disk'
root=Path('/mnt/data-disk/drama-synthesis-catalog/catalog-'+SHA[:12])
if not root.exists():
 root.mkdir(mode=0o755);root.chmod(0o755)
 (root/'manifest.json').write_bytes(raw);(root/'manifest.json').chmod(0o444)
assert (root/'manifest.json').read_bytes()==raw
B=Path('/mnt/data-disk/random-overlay-gpu/backups/20260920-subtemplates80')
B.mkdir(mode=0o700);B.chmod(0o700)
env=Path('/etc/drama-synthesis/cpu.env')
assert ('DRAMA_RANDOM_OVERLAY_MANIFEST_SHA256='+PREVIOUS) in env.read_text()
shutil.copy2(env,B/'cpu.env.before')
units=['drama-material-api.service','drama-material-job-worker.service']
(B/'state-before.json').write_text(json.dumps({'services':{u:subprocess.check_output(['systemctl','show',u,'-p','ActiveState,MainPID,NRestarts']).decode().strip() for u in units}},indent=2))
print(json.dumps({'staged':str(root/'manifest.json'),'sha256':SHA,'backup':str(B)}))
